-- The two checklists published on 2026-11-25: Raising a Problem With a Company
-- (Complaints) and Settling After a Long Flight (Jet Lag).
-- Generated by `python3 tools/checklists_sql.py --since 2026-11-25`; the repo
-- copy in data/checklists.json is the source. Re-applying is harmless.
insert into public.checklists
  (slug, title, description, category, items, cadence, tags, min_level, published_at)
values
  ('raising-a-problem-with-a-company', 'Raising a Problem With a Company', 'Open this when something you paid for went wrong and the thought of chasing it is worse than the problem. It gives you a short script, the order to try things in, and permission to stop once you have done enough.', 'Complaints', '["Write the outcome you want in one line — Knowing what would settle it keeps the call from wandering.", "Gather the dates, amounts and order number — Having the facts to hand halves the length of the conversation.", "Start with the cheapest channel — A chat or an email costs you less than an hour on hold.", "Say the problem, then the fix you want — Leading with the request is clearer than telling the whole story first.", "Keep your tone flat and your facts firm — Calm and specific gets further than angry and vague.", "Note the name and time of each contact — A short record is what makes the second call quick.", "Ask to escalate rather than repeat yourself — The third person at the same level cannot help you.", "Decide the point where you let it go — Some sums are not worth another evening of your life."]'::jsonb, 'as needed', array['Assertiveness', 'Stress', 'Communication']::text[], 1, '2026-11-25T16:00:00+00:00'::timestamptz),
  ('settling-after-a-long-flight', 'Settling After a Long Flight', 'Open this on the first days in a new time zone, when your body is awake at three in the morning and flattened by mid-afternoon. It sets out the handful of things that pull your clock around faster than willpower does.', 'Jet Lag', '["Set your watch to the new time on the plane — Deciding what time it is helps before anything else does.", "Get outside in the morning light — Daylight early in the day is the strongest signal your body reads.", "Keep the first nap under thirty minutes — A short one takes the edge off, and a long one undoes the day.", "Eat at local mealtimes where you can — Meals are a clock your body pays attention to.", "Drink water through the first two days — Travel dries you out, and being dry feels a lot like exhaustion.", "Hold off on the big plans until day three — Arriving and performing on the same day rarely goes well.", "Keep the room dark and cool at night — A cave beats a bedroom while your clock is still wrong.", "Go to bed at the local hour, even if early — One honest night resets more than three half ones."]'::jsonb, 'as needed', array['Sleep', 'Body', 'Self-Care']::text[], 1, '2026-11-25T16:00:00+00:00'::timestamptz)
on conflict (slug) do update set
  title        = excluded.title,
  description  = excluded.description,
  category     = excluded.category,
  items        = excluded.items,
  cadence      = excluded.cadence,
  tags         = excluded.tags,
  min_level    = excluded.min_level,
  published_at = excluded.published_at;
